use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut lc: Vec<int> = []
    let mut rc: Vec<int> = []
    let mut root = -1
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut x = 0
        if parts.len() > 1 {
            x = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            if root == -1 {
                keys.push(x)
                lc.push(-1)
                rc.push(-1)
                root = 0
                println("ok")
            } else {
                let mut cur = root
                let mut done = false
                while !done {
                    let k = keys[cur as usize]
                    if x == k {
                        println("dup")
                        done = true
                    } else if x < k {
                        if lc[cur as usize] == -1 {
                            let n = keys.len() as int
                            keys.push(x)
                            lc.push(-1)
                            rc.push(-1)
                            lc[cur as usize] = n
                            println("ok")
                            done = true
                        } else {
                            cur = lc[cur as usize]
                        }
                    } else {
                        if rc[cur as usize] == -1 {
                            let n = keys.len() as int
                            keys.push(x)
                            lc.push(-1)
                            rc.push(-1)
                            rc[cur as usize] = n
                            println("ok")
                            done = true
                        } else {
                            cur = rc[cur as usize]
                        }
                    }
                }
            }
        } else if cmd == "contains" {
            let mut cur = root
            let mut found = false
            while cur != -1 && !found {
                let k = keys[cur as usize]
                if x == k {
                    found = true
                } else if x < k {
                    cur = lc[cur as usize]
                } else {
                    cur = rc[cur as usize]
                }
            }
            if found {
                println("yes")
            } else {
                println("no")
            }
        } else if cmd == "delete" {
            let mut cur = root
            let mut parent = -1
            let mut isleft = false
            let mut found = false
            while cur != -1 && !found {
                let k = keys[cur as usize]
                if x == k {
                    found = true
                } else if x < k {
                    parent = cur
                    isleft = true
                    cur = lc[cur as usize]
                } else {
                    parent = cur
                    isleft = false
                    cur = rc[cur as usize]
                }
            }
            if !found {
                println("missing")
            } else {
                let l = lc[cur as usize]
                let r = rc[cur as usize]
                if l != -1 && r != -1 {
                    let mut sp = cur
                    let mut s = r
                    while lc[s as usize] != -1 {
                        sp = s
                        s = lc[s as usize]
                    }
                    keys[cur as usize] = keys[s as usize]
                    if sp == cur {
                        rc[cur as usize] = rc[s as usize]
                    } else {
                        lc[sp as usize] = rc[s as usize]
                    }
                } else {
                    let mut child = r
                    if l != -1 {
                        child = l
                    }
                    if parent == -1 {
                        root = child
                    } else if isleft {
                        lc[parent as usize] = child
                    } else {
                        rc[parent as usize] = child
                    }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            if root == -1 {
                println("<empty>")
            } else {
                let mut out: Vec<string> = []
                let mut stack: Vec<int> = []
                let mut cur = root
                while cur != -1 || stack.len() > 0 {
                    while cur != -1 {
                        stack.push(cur)
                        cur = lc[cur as usize]
                    }
                    let n = stack.pop().unwrap_or(0)
                    out.push("${keys[n as usize]}")
                    cur = rc[n as usize]
                }
                println(out.join(" "))
            }
        } else if cmd == "height" {
            let mut best = 0
            if root != -1 {
                let mut stack: Vec<int> = [root]
                let mut depth: Vec<int> = [1]
                while stack.len() > 0 {
                    let n = stack.pop().unwrap_or(0)
                    let d = depth.pop().unwrap_or(0)
                    if d > best {
                        best = d
                    }
                    if lc[n as usize] != -1 {
                        stack.push(lc[n as usize])
                        depth.push(d + 1)
                    }
                    if rc[n as usize] != -1 {
                        stack.push(rc[n as usize])
                        depth.push(d + 1)
                    }
                }
            }
            println("${best}")
        } else if cmd == "min" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur = root
                while lc[cur as usize] != -1 {
                    cur = lc[cur as usize]
                }
                println("${keys[cur as usize]}")
            }
        } else if cmd == "max" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur = root
                while rc[cur as usize] != -1 {
                    cur = rc[cur as usize]
                }
                println("${keys[cur as usize]}")
            }
        }
    }
}

